import pytest

from calibration_target import Record

pytestmark = pytest.mark.verification_kind("unit")

@pytest.mark.verifies("TREQ_CALIBRATION_SUMMARY[revision==1]")
def test_record_summary_omits_sensitive_field_at_level_zero() -> None:
    value = "classified-material-id"
    record = Record(name="public-doc", secret=value, level=0)
    assert record.summary() == {"name": "public-doc"}
